 double angle=0,best=INFINITY;for(int i=0;i<360;++i){double a=i*M_PI/720,c=fit(a).first;if(c<best){best=c;angle=a;}}double a=bounded([&](double x){return fit(x).first;},angle-M_PI/720,angle+M_PI/720);V2 xy=fit(a).second;return V3(xy.x(),xy.y(),(zl+zh)/2);
