static V2 distort(V2 v,const Pair& p){double x=v.x(),y=v.y(),r=x*x+y*y;auto d=p.D;double radial=1+d[0]*r+d[1]*r*r+d[4]*r*r*r;return V2(x*radial+2*d[2]*x*y+d[3]*(r+2*x*x),y*radial+d[2]*(r+2*y*y)+2*d[3]*x*y);}
static V2 undistort(V2 px,const Pair& p){V2 target((px.x()-p.K(0,2))/p.K(0,0),(px.y()-p.K(1,2))/p.K(1,1)),v=target;for(int i=0;i<20;++i){double x=v.x(),y=v.y(),r=v.squaredNorm();auto d=p.D;double rad=1+d[0]*r+d[1]*r*r+d[4]*r*r*r;v=V2((target.x()-2*d[2]*x*y-d[3]*(r+2*x*x))/rad,(target.y()-2*d[3]*x*y-d[2]*(r+2*y*y))/rad);}return v;}
